// فصل 28 از کتاب — تبدیل‌شده از نسخهٔ HTML؛ ویرایش دستی لازم نیست.
// Chapter 28 of the book — converted from the HTML edition; generated file.

export const n = 28;
export const num = "28";
export const title = "GitHub Actions — از رویداد تا استقرار";
export const label = "فصل ۲۸ · GitHub Actions";
export const part = 2;
export const html = "<p class=\"lead\">GitHub Actions یعنی با هر رویداد (مثلاً push یا PR) یک گردش‌کار YAML روی سرور GitHub اجرا شود: تست، lint، ساخت. Secret را در مخزن ذخیره می‌کنی نه داخل کد.</p>\n  <h2><span class=\"hx\"><span class=\"hx-t\">🎯 اهداف یادگیری</span></span></h2>\n<ul>\n<li>workflow، job، step و runner را جدا کنی</li>\n<li>CI را روی PR اجباری کنی</li>\n<li>secret را از Environment بخوانی نه از لاگ</li>\n<li class=\"keep-next\">OIDC را به‌جای Access Key ابری ترجیح دهی</li>\n</ul>\n<div class=\"diagram\">\n<img src=\"/book/figures/actions-flow.svg\" alt=\"جریان GitHub Actions\"/>\n<p class=\"figcap\">شکل ۱۷ — Event → Workflow → Jobs موازی → Checks → Merge/Deploy.</p>\n</div>\n<div class=\"shot\">\n<img src=\"/book/figures/github-actions.svg\" alt=\"اجرای workflow در GitHub\"/>\n<p class=\"figcap\">شکل ۱۸ — صفحهٔ run: جاب‌های lint/test/build و لاگ سبز.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">📄 اولین workflow</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">.github/workflows/ci.yml</span></div><pre><span style=\"color: #FF4689\">name</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #AE81FF\">CI</span>\n<span style=\"color: #FF4689\">on</span><span style=\"color: #F8F8F2\">:</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">pull_request</span><span style=\"color: #F8F8F2\">:</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">push</span><span style=\"color: #F8F8F2\">:</span>\n<span style=\"color: #F8F8F2\">    </span><span style=\"color: #FF4689\">branches</span><span style=\"color: #F8F8F2\">: [main]</span>\n<span style=\"color: #FF4689\">jobs</span><span style=\"color: #F8F8F2\">:</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">test</span><span style=\"color: #F8F8F2\">:</span>\n<span style=\"color: #F8F8F2\">    </span><span style=\"color: #FF4689\">runs-on</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #AE81FF\">ubuntu-latest</span>\n<span style=\"color: #F8F8F2\">    </span><span style=\"color: #FF4689\">steps</span><span style=\"color: #F8F8F2\">:</span>\n<span style=\"color: #F8F8F2\">      - </span><span style=\"color: #FF4689\">uses</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #AE81FF\">actions/checkout@v4</span>\n<span style=\"color: #F8F8F2\">      - </span><span style=\"color: #FF4689\">uses</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #AE81FF\">actions/setup-python@v5</span>\n<span style=\"color: #F8F8F2\">        </span><span style=\"color: #FF4689\">with</span><span style=\"color: #F8F8F2\">:</span>\n<span style=\"color: #F8F8F2\">          </span><span style=\"color: #FF4689\">python-version</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #E6DB74\">&quot;3.13&quot;</span>\n<span style=\"color: #F8F8F2\">      - </span><span style=\"color: #FF4689\">run</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #AE81FF\">pip install -r src/requirements.txt</span>\n<span style=\"color: #F8F8F2\">      - </span><span style=\"color: #FF4689\">run</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #AE81FF\">python src/build.py --html</span>\n</pre></div>\n<p class=\"keep-next\">قواعد:</p>\n<ul>\n<li><strong>pin</strong> اکشن‌ها حداقل روی major (<code>@v4</code>)؛ برای عرضهٔ حساس روی SHA</li>\n<li><code>pull_request</code> از fork به secretهای مخزن دسترسی ندارد (امنیت)</li>\n<li><code>concurrency</code> را برای لغو runهای کهنه روی همان شاخه بگذار</li>\n</ul>\n<h2><span class=\"hx\"><span class=\"hx-t\">♻️ Reusable و matrix</span></span></h2>\n<p class=\"keep-next\">از ۲۰۲۵ می‌توان workflowهای reusable را تو در تو صدا زد (تا سقف مستند GitHub). ماتریس برای چند نسخهٔ Node/Python:</p>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">matrix</span></div><pre><span style=\"color: #FF4689\">strategy</span><span style=\"color: #F8F8F2\">:</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">fail-fast</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #AE81FF\">false</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">matrix</span><span style=\"color: #F8F8F2\">:</span>\n<span style=\"color: #F8F8F2\">    </span><span style=\"color: #FF4689\">node</span><span style=\"color: #F8F8F2\">: [20, 22]</span>\n</pre></div>\n<p><code>workflow_dispatch</code> حالا تا ۲۵ ورودی دارد — برای ops دستی بهتر از JSON هکی.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">🔑 Secrets و OIDC</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">ابر بدون کلید ماندگار</span></div><pre><span style=\"color: #FF4689\">permissions</span><span style=\"color: #F8F8F2\">:</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">id-token</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #AE81FF\">write</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">contents</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #AE81FF\">read</span>\n<span style=\"color: #FF4689\">steps</span><span style=\"color: #F8F8F2\">:</span>\n<span style=\"color: #F8F8F2\">  - </span><span style=\"color: #FF4689\">uses</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #AE81FF\">aws-actions/configure-aws-credentials@v4</span>\n<span style=\"color: #F8F8F2\">    </span><span style=\"color: #FF4689\">with</span><span style=\"color: #F8F8F2\">:</span>\n<span style=\"color: #F8F8F2\">      </span><span style=\"color: #FF4689\">role-to-assume</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #AE81FF\">arn:aws:iam::123:role/gha</span>\n<span style=\"color: #F8F8F2\">      </span><span style=\"color: #FF4689\">aws-region</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #AE81FF\">eu-central-1</span>\n</pre></div>\n<p>GitHub یک JWT کوتاه‌عمر به ابر می‌دهد. اگر ریپو لو برود، کلید AWS در Git نیست.</p>\n<div class=\"callout callout-danger\"><div class=\"callout-title\">echo secret</div>\n<p><code>echo ${{ secrets.X }}</code> در لاگ می‌آید مگر mask شود. حتی mask هم کامل نیست. secret را چاپ نکن.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">🖥️ Actions در VS Code</span></span></h2>\n<p>افزونهٔ GitHub Actions: workflowها، runها، لاگ. <code>gh run watch</code> در ترمینال یکپارچه. روی PR تب Checks همان نتیجه را نشان می‌دهد.</p>\n<div class=\"callout callout-interview\"><div class=\"callout-title\">سؤالات مصاحبه (با پاسخ)</div>\n<p><strong>Junior — runner چیست؟</strong> ماشین (GitHub-hosted یا self-hosted) که stepها را اجرا می‌کند.</p>\n<p><strong>Mid — تفاوت pull_request و pull_request_target؟</strong> دومی در زمینهٔ base با secret اجرا می‌شود — خطرناک اگر checkout روی کد fork باشد.</p>\n<p><strong>Senior — OIDC چه حمله‌ای را می‌بندد؟</strong> کلیدهای بلندمدت ذخیره‌شده در secrets که با log یا memory dump می‌لکد؛ همچنین چرخش دستی.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">✅ چک‌لیست فهم</span></span></h2>\n<div class=\"keep-block\"><div class=\"checklist\">\n<ul>\n<li>CI روی هر PR اجرا می‌شود</li>\n<li>production از Environment با Approve می‌آید</li>\n<li>اکشن‌ها pin شده‌اند</li>\n<li>OIDC را حداقل مفهومی بلدی</li>\n</ul>\n</div><p><strong>فصل بعد:</strong> امنیت زنجیرهٔ تأمین روی GitHub.</p></div>";
export default { n, num, title, label, part, html };
